import sys
from collections import deque

def jump_brute(nums):
    n = len(nums)
    if n == 1:
        return 0
    q = deque([0])
    visited = [False] * n
    visited[0] = True
    steps = 0
    while q:
        steps += 1
        for _ in range(len(q)):
            i = q.popleft()
            for j in range(i + 1, min(n, i + nums[i] + 1)):
                if j == n - 1:
                    return steps
                if not visited[j]:
                    visited[j] = True
                    q.append(j)
    return steps

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(jump_brute(nums))

import sys

def jump_opt(nums):
    n = len(nums)
    pos = n - 1
    steps = 0
    while pos > 0:
        for i in range(n):
            if i + nums[i] >= pos:
                pos = i
                steps += 1
                break
    return steps

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(jump_opt(nums))
